package com.wipro.hibernate;import org.hibernate.*;import java.util.*;public class Main{public static void main(String[]a){try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();for(int i=1;i<=10;i++){Map<String,String>m=new HashMap<>();m.put("Country"+i,"Capital"+i);s.persist(new Continent(i,"Continent"+i,m));}t.commit();System.out.println("10 continent objects persisted.");}HibernateUtil.getSessionFactory().close();}}